<?php $this->assign('title', 'Pedidos de compra'); ?><h1 class="h3 mb-4">Pedidos de compra</h1><div class="card border-0 shadow-sm"><table class="table table-hover mb-0"><thead><tr><th>Número</th><th>Fornecedor</th><th>Status</th><th>Total</th></tr></thead><tbody><?php foreach ($compras as $compra): ?><tr><td><?= $this->Html->link($compra->numero, ['action' => 'view', $compra->id]) ?></td><td><?= h($compra->fornecedor->razao_social ?? '-') ?></td><td><?= h($compra->status) ?></td><td>R$ <?= number_format((float)$compra->valor_total, 2, ',', '.') ?></td></tr><?php endforeach; ?></tbody></table></div>
